-- WhatsNew.lua: generated from CHANGELOG.md by the release (do not edit by hand).
local _, ns = ...
ns.WHATSNEW = {
  { v = "1.0.0-beta.70", fr = { "Marque sur le boss : un clic sur un portrait ciblait bien le boss mais ne posait pas la marque. La marque passe maintenant par la commande du jeu /tm, faite pour les macros (le script utilisé avant est bloqué sur ce client). Pareil pour le bouton de ciblage du guide et sa touche." }, en = { "Boss mark: clicking a portrait now also puts the marker on (game /tm command instead of a blocked script)." } },
  { v = "1.0.0-beta.69", fr = { "Recherche dans le choix des donjons : tape un nom de donjon (ou ZF, BRD, SM), une zone, une quête ou la personne qui la donne ; la recherche couvre tous les onglets et tous les niveaux, sans tenir compte des accents.", "Guide d'un donjon déjà fini : quand toutes ses quêtes sont rendues, le résumé propose « Me guider dans le donjon » : trajet jusqu'à l'entrée, puis boss par boss (tactiques, butin) jusqu'au dernier. Une route de quêtes s'arrête toujours une fois les quêtes finies.", "Objets en récompense dans le résumé : jusqu'à 4 icônes par quête, avec la flèche verte et le pourcentage d'amélioration calculés au niveau de la quête ; le meilleur choix est entouré en or ; le total dit « 3 objets dont 2 améliorations ».", "Clic droit simple = baguette : pour les mages, prêtres et démonistes (ou toute classe avec une baguette), un clic droit seul sur un ennemi lance Tir. Proposé à l'accueil quand tu actives le tir, réglable dans Réglages › Général › Clics.", "Zul'Farrak : Theka le Martyr passe avant Antu'sul dans la visite boss par boss.", "Fenêtre des boss : un boss mort ou hors de vue ne remplace plus son portrait par un rond blanc." }, en = { "Search box in the dungeon picker: dungeon, short name, zone, quest or quest giver, across every tab and level.", "Guide me through the dungeon even when every quest is turned in: entrance, then boss by boss.", "Reward items in the summary with upgrade arrows and the best choice ringed in gold.", "Plain right-click = wand, offered to wand classes, in Settings too.", "Zul'Farrak: Theka the Martyr now comes before Antu'sul.", "Boss panel: no more white disc portraits from dead or unseen bosses." } },
  { v = "1.0.0-beta.68", fr = { "Quoi de neuf : après chaque mise à jour, une fenêtre liste une fois ce qui a changé depuis la version que tu avais (que l'addon ait été mis à jour par WowUp, CurseForge ou à la main). /wlh nouveautes la rouvre." }, en = { "What's new: after each update a window lists the changes since your last version, once; /wlh news reopens it." } },
  { v = "1.0.0-beta.67", fr = { "Clic sur un portrait de boss sans effet : le portrait réagit maintenant à l'appui comme au relâchement, comme les boutons de téléportation et du guide qui marchent sur ce client. Si le boss n'est pas ciblé après le clic, un message le dit dans le chat avec le nom cherché." }, en = { "Boss portraits: click now registered like the working buttons; a chat line says when the boss was not targeted." } },
  { v = "1.0.0-beta.66", fr = { "Fenêtre des boss : les portraits sont rognés et découpés en rond pour que leur bord gris ne dépasse plus ; plus d'icône décorative à côté du nom du donjon." }, en = { "Boss panel: portraits cropped round, no decorative header icon." } },
  { v = "1.0.0-beta.65", fr = { "Fenêtre des boss : plus de croissant gris à droite des portraits (l'anneau n'est gardé que pour les rares, en argent) ; le survol éclaircit doucement au lieu de blanchir le portrait ; la fenêtre se place par défaut en haut à droite de l'écran (comme le minuteur Mythique+), l'épingle la colle au guide si tu préfères." }, en = { "Boss panel: no grey crescents, softer hover, top-right by default." } },
  { v = "1.0.0-beta.64", fr = { "Fenêtre des boss façon Dungeon Journal : en haut, la sortie en cours (Temps, XP, Or) avec « Nouveau run » ; puis les boss en portraits ronds, 5 par ligne, dans l'ordre du donjon (tués : grisés avec une coche) ; puis les Rares en silhouettes grises tant que tu ne les as pas vus, en couleur avec un anneau argenté ensuite. Chaque créature a un vrai visage (modèle du jeu, portrait vu en jeu, ou icône de sa famille). Un clic sur un portrait le cible et le marque. /wlh boss.", "Bilan de sortie : en quittant le donjon, une ligne dans le chat (« Zul'Farrak : 32 min · 38 200 XP · 12 po · 7/7 boss »)." }, en = { "Boss panel like Dungeon Journal: run stats, round portraits, rares greyed until seen." } },
  { v = "1.0.0-beta.63", fr = { "Résumé du donjon plus lisible : bouton « Lancer la route » en bas à droite (ou « Mettre à jour la route » / « Retour à la route » quand une route tourne déjà) ; les quêtes déjà rendues sont repliées en bas ; quand tout est fait, « Tu as déjà rendu toutes les quêtes de … » avec « Choisir un autre donjon » ; une ligne par quête avec niveau, XP et argent ; le total de ta sélection en haut.", "Vue groupe : des colonnes seulement pour les membres dont on connaît l'état (WL Helper ou réponse au partage), une icône par case ; les autres en une ligne « Sans WL Helper : … »." }, en = { "Clearer dungeon summary with a Start the route button." } },
  { v = "1.0.0-beta.62", fr = { "Visite du donjon boss par boss : dans le donjon, une étape par boss dans l'ordre (« Boss 3 sur 7 · Glutton »), avec les objectifs de quête qui s'y rattachent, la tactique (conseils de Naowh lus en direct quand il est installé, sinon nos notes), le chemin et le butin intéressant pour toi (flèche verte et %). L'étape passe toute seule quand le boss meurt (fin de rencontre ou cible morte) et que ses objectifs sont faits ; les boss facultatifs sont passés quand tu avances. Les morts sont gardées pour la sortie en cours (un retour rapide après une mort ne remet rien à zéro).", "Plusieurs spés dans l'infobulle : Réglages › Améliorations › « Spés à comparer » ; une ligne par spé (« Protection +6 % », « Fureur −3 % »), et la flèche des sacs au choix pour ta spé principale ou n'importe laquelle." }, en = { "Dungeon walkthrough boss by boss, auto-advance on kill.", "Several specs in the upgrade tooltip." } },
  { v = "1.0.0-beta.61", fr = { "Le petit suivi est désactivé par défaut : le guide et son bouton « – » (mode réduit) suffisent. Pour le retrouver : /wlh suivi." }, en = { "The small tracker is now opt-in (/wlh suivi)." } },
  { v = "1.0.0-beta.60", fr = { "« Me guider dans le donjon » : le choix des donjons se ferme et le résumé s'ouvre à sa place (il restait ouvert par-dessus)." }, en = { "The dungeon picker closes when the summary opens." } },
  { v = "1.0.0-beta.59", fr = { "Têtes des boss à côté du guide (façon Dungeon Journal) : une petite colonne de portraits à droite, les boss dans l'ordre du donjon puis les rares (cadre argenté, grisés tant que tu ne les as pas vus) ; un clic sur une tête la cible et la marque (crâne pour un boss, étoile pour un rare) ; les boss tués sont grisés avec une coche. Déplaçable, repliable.", "Alerte des rares, partout : son et bandeau « Rare : Nom (niv. N) » avec un bouton pour le cibler et le marquer (hors combat), au plus une fois toutes les 10 minutes par rare.", "Guide compact dans les donjons : le bandeau « Dans le donjon » tient sur une ligne et les descriptions sont raccourcies (le détail dans l'infobulle).", "Petit suivi replié : il affiche l'action à faire maintenant au lieu du seul titre du chapitre, et son infobulle explique ce qu'il est." }, en = { "Boss heads beside the guide: click a head to target and mark it.", "Rare alert with a target-and-mark button." } },
  { v = "1.0.0-beta.58", fr = { "Nouvel écran de bienvenue, en 4 ou 5 étapes courtes avec points de progression, Retour et Passer : à quoi sert WL Helper ; les modules qui t'intéressent (cartes avec icône et une ligne, interrupteur) ; ta spé (seulement si le jeu ne la donne pas) ; le confort (clics éteints par défaut, avertissement pour les chasseurs) ; « C'est prêt » avec de gros boutons pour démarrer et où tout retrouver. /wlh setup le rouvre." }, en = { "New welcome flow: short steps, modules, spec, comfort, ready." } },
  { v = "1.0.0-beta.57", fr = { "Erreur « forbidden object » (Upgrades.lua) avec EllesmereUI : la recherche des boutons de sac ne touche plus les cadres protégés des autres addons.", "Tu n'apparais plus dans « membres sans la quête », quelle que soit la forme de ton nom (avec ou sans royaume)." }, en = { "Upgrades: no more \"forbidden object\" error when scanning bag buttons." } },
  { v = "1.0.0-beta.56", fr = { "Résumé du donjon au lancement d'une route : une case par quête avec l'XP de la quête, l'XP de toute sa chaîne, l'argent, les objets en récompense et les pastilles Élite, Chaîne, Autre donjon, Niveau trop haut ; le total de ta sélection se met à jour en direct ; « Lancer la route » construit le guide avec ce que tu as coché.", "Vue groupe dans le résumé : qui a chaque quête, qui l'a finie, qui doit la prendre, quel prérequis manque ; « Partager » par quête et « Tout partager ».", "Carte d'étape : une seule action en grand (icône, verbe, quête, PNJ et lieu, objectifs, position dans la chaîne), puis « Ensuite chez <PNJ> » en petit. Fini les longues descriptions répétées.", "Objectifs et texte du jeu affichés pour les quêtes de ton journal (« Ancient Mana Crystal : 0/8 »), note de ForeverDungeonJournal quand il est activé, et d'où vient la flèche (« La flèche suit la zone de quête du jeu »).", "Infobulle d'étape réorganisée en blocs, sans doublons ; panneau Étapes ouvert du côté où il y a de la place.", "En-têtes : logo seulement sur l'accueil ; ailleurs une flèche retour. Le bouton « Donjons » remplace l'icône incomprise.", "Texte coupé : une seule mesure de texte fiable partout." }, en = { "Dungeon summary: tick quests and chains with their XP, rewards and warnings.", "Group view: who has what, missing prerequisites, share buttons.", "Step card: one current action, the rest in a short list." } },
}
